  dx = 1; // 初始向右移动，而不是0
  dy = 0;
  score = 0;
  scoreElement.textContent = `得分: ${score}`;
  gameOverElement.style.display = 'none';
  generateFood();
  drawGame();
  startGame();
}

document.addEventListener('keydown', changeDirection);
